with transactions_by_account as (select account_id, count(distinct amount) as unique_txn_types, round(stddev(amount), 2) as stddev_amount from transactions where account_id in (5, 7, 37) group by account_id) select a.account_type, tba.unique_txn_types, tba.stddev_amount from accounts a left join transactions_by_account tba on a.id = tba.account_id where tba.unique_txn_types >= 4 order by a.account_type;
